bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker inspect "$cid" --format 'running={{.State.Running}} restart={{.RestartCount}} image={{.Config.Image}} started={{.State.StartedAt}}'
docker logs --since 45m --tail 150 "$cid" 2>&1 | sed -E 's/[0-9]{6,}:[A-Za-z0-9_-]{20,}/[REDACTED]/g' | head -c 20000
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {menuPage} from './src/telegram/menuPanel.mjs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
 const s=await pool.query("SELECT s.revision,s.state->>'publishing' AS publishing,s.state->>'screen' AS screen,s.state->>'waiting' AS waiting,s.updated_at FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1",['v26nov24invoice']);
 console.log('SESSION',JSON.stringify(s.rows));
 const cols=await pool.query("SELECT table_name,column_name FROM information_schema.columns WHERE table_name IN ('videobot_webhook_updates','videobot_poll_cursor','videobot_poll_quarantine') ORDER BY table_name,ordinal_position");
 console.log('COLUMNS',JSON.stringify(cols.rows));
 const q=await pool.query("SELECT status,count(*)::int AS n,max(updated_at) AS latest FROM videobot_webhook_updates GROUP BY status");
 console.log('WEBHOOK_COUNTS',JSON.stringify(q.rows));
 console.log('MENU',JSON.stringify(menuPage('home').reply_markup.inline_keyboard.map(r=>r.map(x=>x.text))));
 const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
 const base=process.env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org';
 console.log('BOT_API_MODE',base==='http://telegram-bot-api:8081'?'local':'remote');
 for(const method of ['getMe','getWebhookInfo']){
 try{
 const j=await fetch(base+'/bot'+token+'/'+method,{signal:AbortSignal.timeout(12000)}).then(r=>r.json());
 console.log(method,JSON.stringify({ok:j.ok,code:j.error_code,webhook:!!j.result?.url,pending:j.result?.pending_update_count,bot:j.result?.username}));
 }catch(e){console.log('BOT_API_ERROR',e.name,e.cause?.code??'none')}
 }
}catch(e){console.log('DB_ERROR',e.code??'none',e.message?.slice(0,120));process.exitCode=79;}
finally{await pool.end()}
JS
